// func kernel12x32AVX512I(a0, a1 *float32, b0, b1 *int8, k int, c *float32, ldc int, bias *float32, mode int)
//
// Wide outer-product microkernel; see the contract in kernel_go.go. Per k
// step it loads one 16-wide int8 row (VPMOVSXBD, VCVTDQ2PS) from each panel (Z24 from b0, Z25
// from b1), broadcasts the 6 values of each packed strip (Z26-Z31, rows 0-5
// from a0 then rows 6-11 from a1) and issues 24 fused multiply-adds into
// Z0-Z23, where Z(2r) and Z(2r+1) hold columns 0-15 and 16-31 of output row
// r. The main loop runs 2 k steps per iteration, then one more if k is odd.
// The epilogue writes the twelve rows to c, ldc elements apart.
TEXT ·kernel12x32AVX512I(SB), NOSPLIT, $0-72
	MOVQ a0+0(FP), R8
	MOVQ a1+8(FP), R9
	MOVQ b0+16(FP), SI
	MOVQ b1+24(FP), DI
	MOVQ k+32(FP), CX
	MOVQ c+40(FP), DX
	MOVQ ldc+48(FP), R10
	MOVQ bias+56(FP), R11
	MOVQ mode+64(FP), R12
	SHLQ $2, R10 // ldc in bytes

	VPXORD Z0, Z0, Z0
	VPXORD Z1, Z1, Z1
	VPXORD Z2, Z2, Z2
	VPXORD Z3, Z3, Z3
	VPXORD Z4, Z4, Z4
	VPXORD Z5, Z5, Z5
	VPXORD Z6, Z6, Z6
	VPXORD Z7, Z7, Z7
	VPXORD Z8, Z8, Z8
	VPXORD Z9, Z9, Z9
	VPXORD Z10, Z10, Z10
	VPXORD Z11, Z11, Z11
	VPXORD Z12, Z12, Z12
	VPXORD Z13, Z13, Z13
	VPXORD Z14, Z14, Z14
	VPXORD Z15, Z15, Z15
	VPXORD Z16, Z16, Z16
	VPXORD Z17, Z17, Z17
	VPXORD Z18, Z18, Z18
	VPXORD Z19, Z19, Z19
	VPXORD Z20, Z20, Z20
	VPXORD Z21, Z21, Z21
	VPXORD Z22, Z22, Z22
	VPXORD Z23, Z23, Z23

	MOVQ  CX, BX
	SHRQ  $1, BX // iterations of 2 k steps
	ANDQ  $1, CX // one more step if k is odd
	TESTQ BX, BX
	JZ    tail

loop2:
	// k step 0
	VPMOVSXBD 0(SI), Z24
	VCVTDQ2PS Z24, Z24
	VPMOVSXBD 0(DI), Z25
	VCVTDQ2PS Z25, Z25
	VBROADCASTSS 0(R8), Z26
